<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientGrantTypesJsonAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientGrantTypesJsonAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientGrantTypesJsonAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getGrantTypesJson returns null on a freshly created holder.
     */
    public function testGrantTypesJsonNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientGrantTypesJsonAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isGrantTypesJsonAssigned());
        $this->assertNull($holder->getGrantTypesJson());
    }
}
class ImplWithTrustedClientGrantTypesJsonAttributeHolderUnitTest
{
    use TrustedClientGrantTypesJsonAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedGrantTypesJsonRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultGrantTypesJson();
    }
}
